43	\toprule
44	\textbf{格式} & \textbf{组成} & \textbf{用途} \\
45	\midrule
46	Instruction Data & system prompt + instruction + output & SFT \\
47	Preference Data & instruction + chosen answer + rejected answer & DPO/PPO \\
48	\bottomrule
49	\end{tabular}
50	\end{table}
